    /// 语言来源：游戏内选择，然后是启动参数 -language，然后是 Steam 当前游戏语言，最后是简体中文。
    /// 游戏内选择写入 PlayerPrefs 后，下次启动不再被 Steam 覆盖。
    /// </summary>
    public static class GameLocale
        {
            public const string Chinese = "zh-Hans";
            public const string English = "en";
            const string PrefKey = "egg.locale";

        public static event Action Changed;

        public static string Code { get; private set; }
        public static bool IsEnglish { get { return Code != null && Code.StartsWith("en"); } }

        static StringTable _ui;
        static StringTable _lines;
        static bool _applyQueued;
        static Runner _runner;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        static void Boot()
        {
            Code = ResolveInitial();
            LocaleCatalog.EnsureLoaded();
            SteamLanguage.Ready += OnSteamReady;
            var go = new GameObject("GameLocale");
            UnityEngine.Object.DontDestroyOnLoad(go);
            _runner = go.AddComponent<Runner>();
        }

        /// <summary>玩家在游戏里选定语言。这次选择会记住，并压过 Steam。</summary>
        public static void Set(string code)
        {
            code = Normalize(code);
            PlayerPrefs.SetString(PrefKey, code);
            PlayerPrefs.Save();
            Apply(code);
        }

        public static string Normalize(string code)
        {
            if (string.IsNullOrEmpty(code)) return Chinese;
            if (code.StartsWith("en", StringComparison.OrdinalIgnoreCase)) return English;
            return Chinese;
        }

        static string ResolveInitial()
        {
            if (PlayerPrefs.HasKey(PrefKey))
                return Normalize(PlayerPrefs.GetString(PrefKey, Chinese));
            return ResolvePlatform() ?? Chinese;
        }

        static string ResolvePlatform()
        {
            var launch = SteamLocaleMap.FromLaunchOption();
            if (!string.IsNullOrEmpty(launch)) return launch;
            string steam;
            if (SteamLanguage.TryGetLocale(out steam)) return steam;
            return null;
        }

        static void OnSteamReady()
        {
            PullPlatformIfUnset();
        }

        static void PullPlatformIfUnset()
        {
            if (PlayerPrefs.HasKey(PrefKey)) return;
            var platform = ResolvePlatform();
            if (string.IsNullOrEmpty(platform)) return;
            Apply(platform);
        }

        static void Apply(string code)
        {
            code = Normalize(code);
            if (code == Code) return;
            Code = code;
            _ui = null;
            _lines = null;
            ApplySelectedLocale();
            if (Changed != null) Changed();
            if (_runner != null && LocalizationSettings.HasSettings && LocalizationSettings.InitializationOperation.IsDone)
                _runner.StartCoroutine(ReloadTables());
        }

        public static string T(string key)
        {
            var fromTable = FromTable(_ui, key);
            if (!string.IsNullOrEmpty(fromTable)) return fromTable;
            return LocaleCatalog.Ui(key, IsEnglish);
        }

        public static string Line(string source)
        {
            if (string.IsNullOrEmpty(source) || !IsEnglish) return source;
            var fromTable = FromTable(_lines, source);
            if (!string.IsNullOrEmpty(fromTable)) return fromTable;
            return LocaleCatalog.Line(source, true);
        }

        public static string Name(string source)
        {
            if (string.IsNullOrEmpty(source) || !IsEnglish) return source;
            var fromTable = FromTable(_ui, "name." + source);
            if (!string.IsNullOrEmpty(fromTable)) return fromTable;
            return LocaleCatalog.Name(source, true);
        }

        static string FromTable(StringTable table, string key)
        {
            if (table == null || string.IsNullOrEmpty(key)) return null;
            try
            {
                var entry = table.GetEntry(key);
                if (entry == null || string.IsNullOrEmpty(entry.Value)) return null;
                return entry.Value;
            }
            catch (Exception)
            {
                return null;
            }
        }

        static void ApplySelectedLocale()
        {
            if (!LocalizationSettings.HasSettings) return;
            if (!LocalizationSettings.InitializationOperation.IsDone)
            {
                _applyQueued = true;
                return;
            }
            var locale = LocalizationSettings.AvailableLocales.GetLocale(new LocaleIdentifier(Code));
            if (locale != null) LocalizationSettings.SelectedLocale = locale;
        }

        static IEnumerator Initialize()
        {
            yield return LocalizationSettings.InitializationOperation;
            ApplySelectedLocale();
            _applyQueued = false;
            yield return ReloadTables();
using System.Collections.Generic;
using UnityEngine;

namespace EggRescue
{
    /// <summary>
    /// 同步文案表。编辑器会把同一份数据导入 Unity Localization 字符串表。
    /// </summary>
    public static class LocaleCatalog
    {
        public const string ResourcePath = "Localization/catalog";

        static readonly Dictionary<string, string> UiZh = new Dictionary<string, string>();
        static readonly Dictionary<string, string> UiEn = new Dictionary<string, string>();
        static readonly Dictionary<string, string> NamesEn = new Dictionary<string, string>();
        static readonly Dictionary<string, string> LinesEn = new Dictionary<string, string>();
        static bool _loaded;

        public static void EnsureLoaded()
        {
            if (_loaded) return;
            _loaded = true;
            var asset = Resources.Load<TextAsset>(ResourcePath);
            if (asset == null)
            {
                Debug.LogWarning("[Locale] missing Resources/" + ResourcePath);
                return;
            }
            var root = JsonValue.Parse(asset.text);
            ReadUi(root["ui"]);
            ReadPairs(root["names"], NamesEn);
            ReadPairs(root["lines"], LinesEn);
        }

        public static string Ui(string key, bool english)
        {
            EnsureLoaded();
            string value;
            var table = english ? UiEn : UiZh;
            if (key != null && table.TryGetValue(key, out value) && !string.IsNullOrEmpty(value))
                return value;
            if (!english && key != null && UiZh.TryGetValue(key, out value))
                return value;
            return key ?? "";
        }

        public static string Name(string source, bool english)
        {
            if (!english || string.IsNullOrEmpty(source)) return source;
            EnsureLoaded();
            string value;
            if (NamesEn.TryGetValue(source, out value) && !string.IsNullOrEmpty(value))
                return value;
            return source;
        }

        public static string Line(string source, bool english)
        {
            if (!english || string.IsNullOrEmpty(source)) return source;
            EnsureLoaded();
            string value;
            if (LinesEn.TryGetValue(source, out value) && !string.IsNullOrEmpty(value))
                return value;
            return source;
        }

        public static IEnumerable<KeyValuePair<string, string>> UiEntries(bool english)
        {
            EnsureLoaded();
            var table = english ? UiEn : UiZh;
            return table;
        }

        public static Dictionary<string, string> NameEntries()
        {
            EnsureLoaded();
            return NamesEn;
        }

        public static Dictionary<string, string> LineEntries()
        {
            EnsureLoaded();
            return LinesEn;
        }

        public static Dictionary<string, string> UiZhEntries()
        {
            EnsureLoaded();
            return UiZh;
        }

        static void ReadUi(JsonValue array)
        {
            foreach (var item in array.AsArray())
            {
                var key = item["key"].AsString();
                if (string.IsNullOrEmpty(key)) continue;
                UiZh[key] = item["zh"].AsString();
                UiEn[key] = item["en"].AsString();
            }
        }

        static void ReadPairs(JsonValue array, Dictionary<string, string> into)
        {
            foreach (var item in array.AsArray())
            {
                var zh = item["zh"].AsString();
                if (string.IsNullOrEmpty(zh)) continue;
                into[zh] = item["en"].AsString();
            }
        }
    }
}

