    static Vector3 Solve(ThirdPersonCamera camera, Vector3 pivot)
    {
        return (Vector3)Call(camera, "AvoidGeometry", pivot, pivot + Vector3.back * 2.5f);
    }

    static bool Overlap(Vector3 position)
    {
